def oaa_check_compliance_evidence(evidence):
    """Validate + roll up an OAA sprint compliance-evidence document.

    Args:
        evidence: parsed compliance-evidence dict (sprint, controls, ...).
    Returns:
        dict with 'valid', 'violations', 'control_rollup', 'scan_highlights',
        and 'next_sprint_goals'. Never raises on malformed input — returns
        valid=False with a violations list instead.
    """
    violations = []
    if not isinstance(evidence, dict):
        return {
            "valid": False,
            "violations": ["evidence must be an object/dict"],
            "control_rollup": {},
            "scan_highlights": [],
            "next_sprint_goals": [],
        }
    if "sprint" not in evidence:
        violations.append("missing required field 'sprint'")
    elif not isinstance(evidence["sprint"], int) or evidence["sprint"] < 1:
        violations.append("'sprint' must be a positive integer")
    controls = evidence.get("controls")
    rollup = {"total": 0, "pass": 0, "gap": 0, "pending": 0}
    if not isinstance(controls, list) or not controls:
        violations.append("'controls' must be a non-empty array")
    else:
        for i, c in enumerate(controls):
            rollup["total"] += 1
            if not isinstance(c, dict) or "control" not in c or "status" not in c:
                violations.append(f"controls[{i}] missing 'control' or 'status'")
                continue
            status = c["status"]
            if status in ("pass", "gap", "pending"):
                rollup[status] += 1
            else:
                violations.append(f"controls[{i}].status {status!r} not in [pass, gap, pending]")
    scan_highlights = []
    for key, scan in (evidence.get("scan_summary") or {}).items():
        if isinstance(scan, dict) and scan.get("status"):
            findings = 0
            for f in ("critical_findings", "high_findings", "findings"):
                if isinstance(scan.get(f), int):
                    findings += scan[f]
            scan_highlights.append({"scan": key, "status": scan["status"], "tool": scan.get("tool"), "findings": findings})
    return {
        "valid": not violations,
        "violations": violations,
        "control_rollup": rollup,
        "scan_highlights": scan_highlights,
        "next_sprint_goals": evidence.get("next_sprint_goals", []),
    }

def oaa_check_strategy_canvas(canvas):
    """Structural completeness check for an OAA strategy canvas."""
    gaps = []
    if not isinstance(canvas, dict):
        return {"complete": False, "gaps": ["canvas must be an object/dict"], "stats": {}}
    principles = canvas.get("design_principles")
    if not isinstance(principles, list) or not principles:
        gaps.append("'design_principles' must be a non-empty array")
    else:
        for i, p in enumerate(principles):
            for field in ("principle", "axiom", "rationale"):
                if not (isinstance(p, dict) and str(p.get(field) or "").strip()):
                    gaps.append(f"design_principles[{i}] missing {field!r}")
    waves = canvas.get("transformation_waves")
    if not isinstance(waves, list) or not waves:
        gaps.append("'transformation_waves' must be a non-empty array")
    else:
        for i, w in enumerate(waves):
            if not (isinstance(w, dict) and w.get("wave") and w.get("duration")):
                gaps.append(f"transformation_waves[{i}] missing 'wave' or 'duration'")
    resilience = canvas.get("resilience_mapping", [])
    if not isinstance(resilience, list):
        gaps.append("'resilience_mapping', when present, must be an array")
    stats = {
        "design_principles": len(principles) if isinstance(principles, list) else 0,
        "transformation_waves": len(waves) if isinstance(waves, list) else 0,
        "resilience_mappings": len(resilience) if isinstance(resilience, list) else 0,
    }
    return {"complete": not gaps, "gaps": gaps, "stats": stats}
